package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_addPropertyCreator_TriageGen0Test {

    private CreatorCollector creatorCollector;
    private BeanDescription beanDescription;
    private MapperConfig<?> mapperConfig;
    private AnnotatedWithParams creator;

    @Before
    public void setUp() {
        beanDescription = mock(BeanDescription.class);
        mapperConfig = mock(MapperConfig.class);
        creator = mock(AnnotatedWithParams.class);
        // We spy on the object to bypass/control verifyNonDup if necessary, 
        // but since it's protected and part of the logic, we'll use a real instance.
        creatorCollector = new CreatorCollector(beanDescription, mapperConfig);
    }

    @Test
    public void testAddPropertyCreator_SingleProperty() {
        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        when(prop.getName()).thenReturn("prop1");
        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop};

        creatorCollector.addPropertyCreator(creator, true, properties);

        // Verification of side effect: internal state _propertyBasedArgs is updated.
        // Since it's private, we check via behavior if possible or assume success if no exception.
    }

    @Test
    public void testAddPropertyCreator_MultipleProperties_Success() {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("prop1");

        SettableBeanProperty prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("prop2");

        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1, prop2};

        creatorCollector.addPropertyCreator(creator, false, properties);
    }

    @Test
    public void testAddPropertyCreator_DuplicateNames_ThrowsException() {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("duplicate");

        SettableBeanProperty prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("duplicate");

        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1, prop2};

        try {
            creatorCollector.addPropertyCreator(creator, true, properties);
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            org.junit.Assert.assertTrue(e.getMessage().contains("Duplicate creator property \"duplicate\""));
        }
    }

    @Test
    public void testAddPropertyCreator_WithInjectables_SkipsEmptyName() {
        // Property 1: Normal
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("prop1");

        // Property 2: Injectable with empty name (should be skipped)
        SettableBeanProperty prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("");
        when(prop2.getInjectableValueId()).thenReturn("someId");

        // Property 3: Same name as prop1 (if prop2 wasn't skipped, this would throw)
        SettableBeanProperty prop3 = mock(SettableBeanProperty.class);
        when(prop3.getName()).thenReturn("prop1");

        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1, prop2, prop3};

        // This should still throw because prop1 and prop3 have same name, 
        // but it proves prop2 was processed by the loop.
        try {
            creatorCollector.addPropertyCreator(creator, true, properties);
            org.junit.Assert.fail("Expected IllegalArgumentException due to prop1/prop3");
        } catch (IllegalArgumentException e) {
            org.junit.Assert.assertTrue(e.getMessage().contains("Duplicate creator property \"prop1\""));
        }
    }

    @Test
    public void testAddPropertyCreator_WithInjectables_NoDuplicateWithEmptyName() {
        // Property 1: Normal
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("prop1");

        // Property 2: Injectable with empty name (skipped)
        SettableBeanProperty prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("");
        when(prop2.getInjectableValueId()).thenReturn("someId");

        // Property 3: Same name as prop1 (should be okay if prop2 is skipped and we use different names)
        // Let's make prop3 different to ensure success
        SettableBeanProperty prop3 = mock(SettableBeanProperty.class);
        when(prop3.getName()).thenReturn("prop3");

        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1, prop2, prop3};

        creatorCollector.addPropertyCreator(creator, true, properties);
    }

    @Test
    public void testAddPropertyCreator_EmptyPropertiesArray() {
        SettableBeanProperty[] properties = new SettableBeanProperty[0];
        creatorCollector.addPropertyCreator(creator, true, properties);
    }

    @Test
    public void testAddPropertyCreator_InjectableWithNonEmptyName_NotSkipped() {
        // If name is NOT empty but it's an injectable, it should NOT be skipped.
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("name");

        SettableBeanProperty prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("name"); // Duplicate name
        when(prop2.getInjectableValueId()).thenReturn("someId");

        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1, prop2};

        try {
            creatorCollector.addPropertyCreator(creator, true, properties);
            org.junit.Assert.fail("Expected exception for duplicate name even if injectable");
        } catch (IllegalArgumentException e) {
            org.junit.Assert.assertTrue(e.getMessage().contains("Duplicate creator property \"name\""));
        }
    }
}
